import numpy as np

def split_heads(M, h):
    """(T, d) -> (h, T, d // h): head k gets columns k*dh to (k+1)*dh of every row."""
    T, d = M.shape
    return M.reshape(T, h, d // h).transpose(1, 0, 2)

def merge_heads(Mh):
    """(h, T, dh) -> (T, h * dh): the exact inverse of split_heads."""
    h, T, dh = Mh.shape
    return Mh.transpose(1, 0, 2).reshape(T, h * dh)
